INSERT INTO `tours` VALUES (1,'Tour ─É├á Nß║╡ng - Hß╗Öi An','Du lß╗ïch miß╗ün Trung 4 ng├áy 3 ─æ├¬m',5500000,6200000,20,'2026-09-01','https://dreamtravel.com.vn/Data/ResizeImage/~/uploads/images/uy├¬n 2020/─æ├á nß║╡ng/cau_vang_da_nangx298x220x2.jpg','H├á Nß╗Öi','─É├á Nß║╡ng - Hß╗Öi An','4 ng├áy 3 ─æ├¬m','2026-08-31 17:00:00','Viß╗çt Nam','APPROVED',NULL),(2,'Tour SaPa 3N2D bß║▒ng ├┤ t├┤ trß╗ìn g├│i tß╗½ H├á Nß╗Öi','Kh├ím ph├í ruß╗Öng bß║¡c thang v├á bß║ún l├áng T├óy Bß║»c vß╗¢i lß╗ïch tr├¼nh trß╗ìn g├│i.',2590000,2990000,13,'2026-09-15','https://images.unsplash.com/photo-1570366583862-f91883984fde?auto=format&fit=crop&w=1200&q=85','H├á Nß╗Öi','SaPa','3 ng├áy 2 ─æ├¬m','2026-09-18 09:01:10','Viß╗çt Nam','APPROVED',NULL),(3,'Tour Ph├║ Quß╗æc','Nghß╗ë d╞░ß╗íng ─æß║úo ngß╗ìc',6800000,0,10,'2026-10-05','https://dreamtravel.com.vn/Data/ResizeImage/~/uploads/images/uy├¬n 2020/ph├║ quß╗æc/du_lich_Phu_quocx298x220x2.jpg','H├á Nß╗Öi','Ph├║ Quß╗æc','3 ng├áy 2 ─æ├¬m',NULL,'Viß╗çt Nam','APPROVED',NULL),(5,'H├á Nß╗Öi - Nghß╗ë D╞░ß╗íng Du Thuyß╗ün Hß║í Long Cao Cß║Ñp - Ninh B├¼nh - B├íi ─É├¡nh - Tr├áng An - Tuyß╗çt Tß╗ïnh Cß╗æc','1. Th├┤ng tin tß╗òng quan\r\nThß╗¥i gian: 4 ng├áy 3 ─æ├¬m.\r\n\r\nPh╞░╞íng tiß╗çn di chuyß╗ân: M├íy bay, xe du lß╗ïch v├á du thuyß╗ün.\r\n\r\nC├íc ─æiß╗âm tham quan ch├¡nh: Ngß╗º ─æ├¬m tr├¬n Du thuyß╗ün Hß║í Long cao cß║Ñp, Ch├╣a B├íi ─É├¡nh, Khu du lß╗ïch sinh th├íi Tr├áng An v├á Tuyß╗çt Tß╗ïnh Cß╗æc.\r\n\r\nThß╗¥i ─æiß╗âm l├╜ t╞░ß╗ƒng: C├│ thß╗â khß╗ƒi h├ánh v├áo c├íc thß╗¥i ─æiß╗âm quanh n─âm.\r\n\r\n2. Nhß╗»ng trß║úi nghiß╗çm nß╗òi bß║¡t\r\nNghß╗ë d╞░ß╗íng tr├¬n vß╗ïnh: ─Éiß╗âm nhß║Ñn ─æß║╖c biß╗çt cß╗ºa ch╞░╞íng tr├¼nh l├á 1 ─æ├¬m nghß╗ë d╞░ß╗íng tr├¬n du thuyß╗ün cao cß║Ñp tß║íi Vß╗ïnh Hß║í Long, n╞íi du kh├ích c├│ thß╗â ngß║»m cß║únh vß╗ïnh, tham gia lß╗¢p hß╗ìc nß║Ñu c├íc m├│n ─ân Viß╗çt v├á tß║¡p Th├íi Cß╗▒c Quyß╗ün v├áo buß╗òi s├íng.\r\n\r\nKh├ím ph├í v─ân h├│a & thi├¬n nhi├¬n: H├ánh tr├¼nh sß║╜ ─æ╞░a du kh├ích ─æi thuyß╗ün kh├ím ph├í cß║únh sß║»c tß║íi Tr├áng An, v├úng cß║únh tß║íi Tuyß╗çt Tß╗ïnh Cß╗æc v├á chi├¬m b├íi kh├┤ng gian t├óm linh tß║íi Ch├╣a B├íi ─É├¡nh.\r\n\r\nTrß║úi nghiß╗çm ß║⌐m thß╗▒c: Du kh├ích sß║╜ ─æ╞░ß╗úc th╞░ß╗ƒng thß╗⌐c ─æa dß║íng c├íc loß║íi h├¼nh ß║⌐m thß╗▒c nh╞░ bß╗»a s├íng buffet, bß╗»a s├íng theo thß╗▒c ─æ╞ín, buffet du thuyß╗ün, hß║úi sß║ún v├á c├íc m├│n ─ân ─æß║╖c sß║ún ─æß╗ïa ph╞░╞íng mang ─æß║¡m tinh hoa ß║⌐m thß╗▒c Bß║»c Bß╗Ö.\r\n\r\nH╞░ß╗¢ng ─æß║┐n du lß╗ïch bß╗ün vß╗»ng: Tour lß╗ông gh├⌐p c├íc yß║┐u tß╗æ m├┤i tr╞░ß╗¥ng v├á cß╗Öng ─æß╗ông, khuyß║┐n kh├¡ch trß║úi nghiß╗çm thi├¬n nhi├¬n chuy├¬n s├óu c┼⌐ng nh╞░ gß║»n kß║┐t vß╗¢i c├íc dß╗ïch vß╗Ñ l╞░u tr├║ v├á sß║ún vß║¡t bß║ún ─æß╗ïa cß╗ºa ─æß╗ïa ph╞░╞íng.\r\n\r\n3. T├│m tß║»t lß╗ïch tr├¼nh chuyß║┐n ─æi\r\nNg├áy 1 (Tp. Hß╗ô Ch├¡ Minh ΓÇô H├á Nß╗Öi): H├ánh kh├ích di chuyß╗ân tß╗½ TP.HCM ra H├á Nß╗Öi (Bao gß╗ôm ─ân tr╞░a v├á ─ân tß╗æi).\r\n\r\nNg├áy 2 (H├á Nß╗Öi ΓÇô Hß║í Long): Di chuyß╗ân ─æß║┐n Hß║í Long, trß║úi nghiß╗çm c├íc dß╗ïch vß╗Ñ v├á ngß╗º ─æ├¬m tr├¬n du thuyß╗ün (Bao gß╗ôm ─ân s├íng, ─ân tr╞░a v├á ─ân tß╗æi).\r\n\r\nNg├áy 3 (Hß║í Long ΓÇô Ninh B├¼nh): Khß╗ƒi h├ánh tß╗½ Hß║í Long ─æi Ninh B├¼nh (Bao gß╗ôm ─ân s├íng, ─ân tr╞░a v├á ─ân tß╗æi).\r\n\r\nNg├áy 4 (Ninh B├¼nh ΓÇô Nß╗Öi B├ái ΓÇô Tp. Hß╗ô Ch├¡ Minh): Tiß║┐p tß╗Ñc tham quan Ninh B├¼nh, sau ─æ├│ di chuyß╗ân ra s├ón bay Nß╗Öi B├ái ─æß╗â bay vß╗ü Tp. Hß╗ô Ch├¡ Minh (Bao gß╗ôm ─ân s├íng v├á ─ân tr╞░a).\r\n\r\n4. Ch╞░╞íng tr├¼nh khuyß║┐n m├úi tham khß║úo\r\nH├ánh tr├¼nh n├áy ─æang c├│ ╞░u ─æ├úi m├╣a thu mang t├¬n ΓÇ£KHß╗₧I H├ÇNH M├ÖA V├ÇNG ΓÇô ─É├ôN NG├ÇN ─ÉIß╗ÇU MAYΓÇ¥ vß╗¢i mß╗⌐c giß║úm gi├í c├│ thß╗â l├¬n ─æß║┐n 3.000.000 VN─É.\r\n\r\n╞»u ─æ├úi n├áy ├íp dß╗Ñng cho c├íc booking mß╗¢i tß╗½ ng├áy 15/08 ─æß║┐n 31/10/2026, d├ánh cho tour trß╗ìn g├│i khß╗ƒi h├ánh trong giai ─æoß║ín tß╗½ 01/09/2026 ─æß║┐n hß║┐t 30/11/2026 (y├¬u cß║ºu thanh to├ín ─æß╗º 100%).\r\n\r\nNgo├ái ra, t├╣y theo mß╗⌐c gi├í trß╗ï cß╗ºa booking, kh├ích h├áng c├│ thß╗â ─æ╞░ß╗úc tß║╖ng th├¬m gß╗æi k├¬ cß